 void next(){if(over||paused)return;int M=stageMax(),N=Math.min(min(),Math.max(0,M-1)),type=r.nextInt(level.equals("CP")?2:3);if(type==2&&!multiply(M))addition(N,M);else if(type==1)subtraction(N,M);else addition(N,M);if(diff.equals("Légendaire")){inputV.setTag("");inputV.setText("—");}else fill(M);}void addition(int N,int M){answer=N+r.nextInt(Math.max(1,M-N+1));int a=N+r.nextInt(Math.max(1,answer-N+1));opV.setText(a+" + "+(answer-a)+" = ?");}void subtraction(int N,int M){int a,b,k=0;do{a=N+r.nextInt(Math.max(1,M-N+1));b=N+r.nextInt(Math.max(1,M-N+1));if(b>a){int t=a;a=b;b=t;}k++;}while(a+b>100&&k<400);while(a+b>100&&b>0)b--;answer=a-b;opV.setText(a+" − "+b+" = ?");}boolean multiply(int M){ArrayList<int[]> list=new ArrayList<>();for(int a=2;a<=Math.max(3,Math.min(10,mm()));a++)for(int b=3;b<=10;b++)if(a*b<=M)list.add(new int[]{a,b});if(list.isEmpty())return false;int[] x=list.get(r.nextInt(list.size()));answer=x[0]*x[1];opV.setText(x[0]+" × "+x[1]+" = ?");return true;}void fill(int M){int gi=r.nextInt(3),v[]={-1,-1,-1};v[gi]=answer;for(int i=0;i<3;i++)if(i!=gi){int z,k=0;do{int delta=1+r.nextInt(Math.max(3,Math.min(15,M/10+2)));z=Math.max(0,answer+(r.nextBoolean()?delta:-delta));k++;}while((z==answer||z==v[0]||z==v[1]||z==v[2])&&k<100);if(z==answer)z=answer+1+i;v[i]=z;}for(int i=0;i<3;i++){choices[i].setText(String.valueOf(v[i]));choices[i].setTag(v[i]);choices[i].setEnabled(true);}}
