 void timer(){stopTimer();tick=new Runnable(){public void run(){if(timerV!=null&&!paused&&!over)timerV.setText(time(elapsed()));if(!over)h.postDelayed(this,100);}};h.post(tick);}void stopTimer(){if(tick!=null)h.removeCallbacks(tick);tick=null;}long elapsed(){long now=paused?pauseMs:System.currentTimeMillis();return Math.max(0,now-startMs-pausedTotal);}String time(long m){long s=m/1000;return String.format(Locale.FRANCE,"%02d:%02d.%d",s/60,s%60,(m%1000)/100);}String secs(long m){return String.format(Locale.FRANCE,"%.1f s",m/1000.0);}void hold(){if(!paused){paused=true;pauseMs=System.currentTimeMillis();}}void resume(){if(paused){paused=false;pausedTotal+=System.currentTimeMillis()-pauseMs;}}void pause(Button b){if(!paused){hold();b.setText("▶ Reprendre");msgV.setText("⏸ PAUSE");}else{resume();b.setText("⏸ Pause");msgV.setText("C'est reparti !");}}void leave(){boolean was=paused;if(diff.equals("Chrono")&&!paused)hold();new AlertDialog.Builder(this).setTitle("Quitter la partie ?").setMessage("La partie en cours sera perdue.").setNegativeButton("Continuer",(x,w)->{if(diff.equals("Chrono")&&!was)resume();full();}).setPositiveButton("Quitter",(x,w)->home()).setOnCancelListener(x->{if(diff.equals("Chrono")&&!was)resume();full();}).show();}
